public class Main {
    int firstMissingPositive(int[] nums) {
        int candidate = 1;
        while (true) {
            boolean found = false;
            for (int num : nums) {                                    // linear search through the whole array
                if (num == candidate) { found = true; break; }
            }
            if (!found) return candidate;
            candidate++;
        }
    }

    public static void main(String[] args) {
        int[] nums = {3, 4, -1, 1};
        Main solution = new Main();
        System.out.println(solution.firstMissingPositive(nums));
    }
}

