def first_missing_positive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            target = nums[i] - 1
            nums[i], nums[target] = nums[target], nums[i]           # place this value at its own index
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1                                              # first index that does not match
    return n + 1


if __name__ == "__main__":
